import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.hwbV7reR.js";const p=JSON.parse('{"title":"Гарантии жизненного цикла","description":"","frontmatter":{},"headers":[],"relativePath":"lifecycle.md","filePath":"lifecycle.md","lastUpdated":1791695486000}'),a={name:"lifecycle.md"};function c(_,e,n,s,i,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="гарантии-жизненного-цикла" tabindex="-1">Гарантии жизненного цикла <a class="header-anchor" href="#гарантии-жизненного-цикла" aria-label="Permalink to &quot;Гарантии жизненного цикла&quot;">​</a></h1><p>Это контракт текущего поведения и обязательные условия будущего рефакторинга. Реализация проверяется тестами с закреплённым агентом, без реальных VPN-серверов. Общий набор испытаний драйверов находится в tests/test_driver_contract.py.</p><h2 id="идентификаторы" tabindex="-1">Идентификаторы <a class="header-anchor" href="#идентификаторы" aria-label="Permalink to &quot;Идентификаторы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Значение</th><th>Владелец и срок жизни</th></tr></thead><tbody><tr><td><code>device_id</code></td><td>Канонический идентификатор устройства/доступа от доверенного backend; право на слот проверяет backend</td></tr><tr><td><code>connection_id</code></td><td>Стабильный идентификатор подключения оркестратора; сохраняется при переносе между узлами</td></tr><tr><td><code>node_id</code> / <code>server_id</code></td><td>Запись узла и ожидаемая идентичность агента; подмена адреса не разрешает принять чужой сервер</td></tr><tr><td><code>remote_id</code></td><td>Идентификатор peer на конкретном узле; может измениться при переносе</td></tr><tr><td><code>binding_key</code></td><td>Идентичность создания peer; повтор после потери ответа использует прежнее значение</td></tr><tr><td><code>idempotency_key</code></td><td>Идентичность конкретной операции; таймаут не разрешает заменить ключ</td></tr><tr><td><code>revision</code></td><td>Ревизия полученных параметров; повтор старой ревизии не должен переключать устройство обратно</td></tr></tbody></table><p>Уникальность журнала назначений задана для пары <code>(device_id, protocol)</code>. Это техническое ограничение, а не учёт оплаченных слотов. Текущий сценарий create сначала использует совместимое существующее назначение; несовместимый запрос не разрешает молча создать второй доступ. Межпротокольная миграция пока не реализована.</p><h2 id="состояние-доступа-и-состояние-сети" tabindex="-1">Состояние доступа и состояние сети <a class="header-anchor" href="#состояние-доступа-и-состояние-сети" aria-label="Permalink to &quot;Состояние доступа и состояние сети&quot;">​</a></h2><p>В модели Connection допустимы <code>pending</code>, <code>active</code>, <code>disabled</code>, <code>expired</code>, <code>conflict</code>. HTTP-слой описывает проверенный ответ агента; не каждое промежуточное состояние возвращается клиенту как Connection — операция может завершиться машинной ошибкой.</p><p><code>active</code> означает разрешённый доступ на узле. Это не свидетельство свежего handshake, работающего DNS или доступности сайта с устройства пользователя. Оркестратор видит свою связь с API агента; клиент наблюдает собственную сеть и туннель. Таймаут API, ошибка сайта и недоступность туннеля не взаимозаменяемы. Проверка <code>/v1/health</code> подтверждает работу процесса, а не исправность всех VPN-узлов.</p><h2 id="первое-создание" tabindex="-1">Первое создание <a class="header-anchor" href="#первое-создание" aria-label="Permalink to &quot;Первое создание&quot;">​</a></h2><ol><li>Backend проверяет владельца, подтверждение аккаунта, срок и доступный слот.</li><li>Оркестратор проверяет входной контракт и совместимость клиента/драйвера.</li><li>Для нового назначения получает свежие наблюдения и резервирует место в SQLite. При подсчёте учитывает конкурентные назначения и незавершённые переключения.</li><li>Создаёт peer на закреплённом узле с сохранённой идентичностью.</li><li>Проверяет ответ и возвращает стабильный connection_id.</li></ol><p>Потеря ответа между шагами 4 и 5 оставляет неопределённый результат, а не доказательство отсутствия peer. Повтор восстанавливает то же назначение на том же узле. Новая цель или новый binding_key в обход журнала недопустимы.</p><h2 id="переключение-узла" tabindex="-1">Переключение узла <a class="header-anchor" href="#переключение-узла" aria-label="Permalink to &quot;Переключение узла&quot;">​</a></h2><p>Переключение сегодня сохраняет протокол. В таблице switches сохраняются состояния:</p><table tabindex="0"><thead><tr><th>Состояние</th><th>Значение и допустимое продолжение</th></tr></thead><tbody><tr><td><code>reserved</code></td><td>Цель, ключ операции и binding_key сохранены; подтвердить прекращение старого доступа</td></tr><tr><td><code>source_revoked</code></td><td>Прекращение доступа подтверждено; создать/найти peer на закреплённой цели и проверить его</td></tr><tr><td><code>complete</code></td><td>Назначение и результат переключения опубликованы одной транзакцией</td></tr><tr><td><code>cancelled</code></td><td>Просроченная операция закрыта после проверки отзыва; новый доступ не создаётся</td></tr></tbody></table><p>При таймауте состояние остаётся на последнем подтверждённом шаге. Повтор может снова вызвать агент, поэтому его операции должны быть идемпотентными. Фоновый обработчик продолжает ту же операцию после перезапуска; третий сервер не выбирается.</p><p>Новый доступ выдаётся после подтверждённого отзыва источника. Исключение для полного отказа API допускается только при проверенном механизме коротких разрешений (leases) и завершённом безопасном ожидании. Обычный таймаут не заменяет отзыв. На узлах без leases автоматическое завершение переноса при недоступном источнике невозможно. Подробнее: <a href="./node-agent.html">контракт агента</a>.</p><p>Запрос disable во время переключения сохраняет <code>disable_requested</code> до продолжения операции. Восстановление не должно опубликовать активный доступ после этого запроса. Истёкший срок не продлевается автоматически. Просроченная операция отменяется после проверки отзыва обеих сторон. Старый завершённый запрос не заменяет новое назначение.</p><h2 id="выдача-параметров-и-экспорт" tabindex="-1">Выдача параметров и экспорт <a class="header-anchor" href="#выдача-параметров-и-экспорт" aria-label="Permalink to &quot;Выдача параметров и экспорт&quot;">​</a></h2><p>Перед выдачей проверяются принадлежность устройству, совместимость, идентичность узла, срок, запрет доступа и незавершённые операции. Изменение назначения и выдача параметров используют общую блокировку. Экспорт не создаёт peer, не продлевает срок и не переключает сервер; после обращения к агенту срок проверяется повторно.</p><p>Формат выбирается из возможностей адаптера. Неизвестный формат или несовместимый клиент получают явную ошибку, без скрытой подмены протокола. Конфигурационные документы проходят через память и не сохраняются в центральном журнале.</p><h2 id="карта-регрессионных-проверок" tabindex="-1">Карта регрессионных проверок <a class="header-anchor" href="#карта-регрессионных-проверок" aria-label="Permalink to &quot;Карта регрессионных проверок&quot;">​</a></h2><p>Исходники тестов находятся в <a href="https://github.com/UndercoreCo/orchestrator/tree/main/tests" target="_blank" rel="noreferrer">tests</a>.</p><table tabindex="0"><thead><tr><th>Гарантия</th><th>Существующая проверка</th></tr></thead><tbody><tr><td>Повтор и конкурентное создание не дают второго peer</td><td><code>test_agent_gateway.py</code>: <code>test_concurrent_creates_consume_one_assignment</code></td></tr><tr><td>Потеря ответа сохраняет узел и идентичность</td><td><code>test_agent_gateway.py</code>: <code>test_lost_response_recovers_original_node_peer_and_assignment</code></td></tr><tr><td>Неверный server_id блокирует команды</td><td><code>test_agent_gateway.py</code>: <code>test_server_identity_mismatch_blocks_commands_even_for_existing_assignment</code></td></tr><tr><td>Чужое устройство не получает и не отзывает доступ</td><td><code>test_connection_contract.py</code>: <code>test_wrong_device_cannot_read_export_or_revoke</code></td></tr><tr><td>Неподтверждённый отзыв блокирует выдачу на цели</td><td><code>test_node_switch.py</code>: <code>test_revoke_unreachable_never_creates_target_and_can_resume</code></td></tr><tr><td>Перезапуск продолжает прежнее переключение</td><td><code>test_node_switch.py</code>: <code>test_lost_response_recovers_same_switch_after_restart</code></td></tr><tr><td>Намерение отключить сохраняется при отказе цели</td><td><code>test_node_switch.py</code>: <code>test_disable_intent_survives_target_outage_and_switch_retry</code></td></tr><tr><td>Перезагрузка и скачок часов не сокращают безопасное ожидание</td><td><code>test_leases.py</code>: <code>test_wall_clock_jump_and_host_restart_cannot_shorten_fence</code></td></tr><tr><td>Старая revision не вызывает обратное переключение</td><td><code>test_recovery.py</code>: <code>test_stale_revision_returns_new_manifest_without_switch</code></td></tr><tr><td>Экспорт не создаёт назначения</td><td><code>test_exports.py</code>: <code>test_exports_are_adapter_owned_and_do_not_create_assignments</code></td></tr><tr><td>Неудачное обновление сохраняет актуальный журнал</td><td><code>test_standalone.py</code>: <code>test_failed_health_rolls_back_code_without_restoring_live_journal</code></td></tr></tbody></table><p>Эти проверки подтверждают конкретные сценарии. Они не заменяют испытания реального VPN-движка, сети клиента, нагрузки и установки на чистом сервере.</p>',24)])])}const b=t(a,[["render",c]]);export{p as __pageData,b as default};
